window.__BAKE_HIST_GZ__="";
window.__BAKE_HIST_RDY__=(async function(){try{if(window.__BAKE_HIST_DONE__)return true;var s=window.__BAKE_HIST_GZ__;if(!s)return false;if(typeof DecompressionStream!=='function')throw new Error('无 DecompressionStream');var bin=atob(s),n=bin.length,u=new Uint8Array(n);for(var i=0;i<n;i++)u[i]=bin.charCodeAt(i);var buf=await new Response(new Blob([u]).stream().pipeThrough(new DecompressionStream('gzip'))).arrayBuffer();var h=JSON.parse(new TextDecoder('utf-8').decode(new Uint8Array(buf)));var bk=window.__BAKE_RAW__;if(!bk||!bk.matches)return false;if(h.matches&&h.matches.r)bk.matches.r=bk.matches.r.concat(h.matches.r);if(h.packs)for(var k in h.packs){if(!bk.packs[k])bk.packs[k]=h.packs[k];}window.__BAKE_HIST_DONE__=1;return true;}catch(e){window.__BAKE_HIST_ERR__=String((e&&e.message)||e);console.warn('[bake] 历史快照合并失败:',e);return false;}})();
